window.KHO_DATA_L4_MITHUAT = [
{"lop":4,"mon":"Mĩ thuật","tuan":1,"tiet":1,"bai":"Chủ đề 1: Vẻ đẹp trong điêu khắc đình làng Việt Nam (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình trong chạm khắc gỗ và tượng tròn ở đình làng.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý, có ý thức giữ gìn di sản mĩ thuật của quê hương, đất nước.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được đặc điểm tạo hình của chạm khắc đình làng qua ảnh phóng to.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; đất nặn, giấy màu, vật liệu tái sử dụng để đắp nổi hoặc nặn hình khối 3D (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong điêu khắc đình làng việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về vẻ đẹp tạo hình trong chạm khắc gỗ và tượng tròn ở đình làng.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở tư liệu ảnh độ phân giải cao chụp mảng chạm khắc gỗ và tượng tròn ở đình làng, phóng to đến từng nhát đục để HS thấy độ nông sâu của mảng chạm; HS đọc phần chú thích ghi tên đình, địa phương và niên đại đi kèm mỗi ảnh.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tra cứu trong nguồn GV chỉ định để tìm một ngôi đình ở tỉnh mình, ghi lại tên đình và một chi tiết chạm khắc đặc sắc kèm nơi lấy thông tin.\n⚠ (Miền 4: An toàn) Ảnh tư liệu di sản phải lấy từ trang của bảo tàng, cơ quan văn hoá hoặc sách đã xuất bản và ghi rõ nguồn khi đưa vào bài; không tải ảnh trôi nổi không rõ nơi chụp rồi chú thích sai tên di tích.","hs":"- HS nêu được đặc điểm tạo hình của chạm khắc đình làng qua ảnh phóng to.\n- HS tìm và ghi được nguồn tư liệu về một ngôi đình ở địa phương."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 1, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":2,"tiet":2,"bai":"Chủ đề 1: Vẻ đẹp trong điêu khắc đình làng Việt Nam (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện vẻ đẹp tạo hình trong chạm khắc gỗ và tượng tròn ở đình làng thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý, có ý thức giữ gìn di sản mĩ thuật của quê hương, đất nước.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nắm được thứ tự các bước làm sản phẩm nhờ tự tua chậm clip.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; đất nặn, giấy màu, vật liệu tái sử dụng để đắp nổi hoặc nặn hình khối 3D (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong điêu khắc đình làng việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác vẻ đẹp tạo hình trong chạm khắc gỗ và tượng tròn ở đình làng).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV cho HS xem clip quay quá trình một nghệ nhân đục một mảng chạm từ khối gỗ phẳng đến khi hoàn thiện; HS tự tua chậm hoặc xem lại đoạn khó trên máy của nhóm để nắm thứ tự các bước, việc mà xem GV làm mẫu một lần không kịp ghi nhớ.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS lập bảng các bước thực hiện sản phẩm của mình dựa trên clip: vẽ phác, tạo mảng lớn, tỉa chi tiết, làm nhẵn; nêu bước nào mình thấy khó và dự tính cách khắc phục.\n⚠ (Miền 4: An toàn) Clip mở đúng đường dẫn GV cung cấp, không bấm sang các clip gợi ý bên cạnh; khi làm sản phẩm không dùng dao, đục sắc mà dùng que gỗ, bút hết mực để tạo nét trên đất nặn.","hs":"- HS nắm được thứ tự các bước làm sản phẩm nhờ tự tua chậm clip.\n- HS lập được bảng các bước và dự tính cách xử lí bước khó."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 1, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":3,"tiet":3,"bai":"Chủ đề 1: Vẻ đẹp trong điêu khắc đình làng Việt Nam (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện vẻ đẹp tạo hình trong chạm khắc gỗ và tượng tròn ở đình làng theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý, có ý thức giữ gìn di sản mĩ thuật của quê hương, đất nước.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; đất nặn, giấy màu, vật liệu tái sử dụng để đắp nổi hoặc nặn hình khối 3D (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong điêu khắc đình làng việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 4).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện vẻ đẹp tạo hình trong chạm khắc gỗ và tượng tròn ở đình làng (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng đất nặn, giấy màu, vật liệu tái sử dụng để đắp nổi hoặc nặn hình khối 3D hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 1, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":4,"tiet":4,"bai":"Chủ đề 1: Vẻ đẹp trong điêu khắc đình làng Việt Nam (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý, có ý thức giữ gìn di sản mĩ thuật của quê hương, đất nước.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS chụp và đưa được ảnh sản phẩm vào trang trưng bày kèm thông tin tác giả.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; đất nặn, giấy màu, vật liệu tái sử dụng để đắp nổi hoặc nặn hình khối 3D (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong điêu khắc đình làng việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS tự chụp sản phẩm của mình bằng thiết bị của lớp, chọn hướng sáng chếch để mảng chạm nổi rõ, rồi đưa ảnh vào trang trưng bày chung kèm tên tác giả và tên sản phẩm.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS xem trang trưng bày và viết một lời nhận xét cho sản phẩm của bạn theo mẫu: một điều em thích và một điều em muốn hỏi thêm.\n⚠ (Miền 4: An toàn) Chỉ chụp sản phẩm, không chụp bạn khi bạn chưa đồng ý; nhận xét phải nêu cụ thể vào sản phẩm chứ không bình luận về người; trang trưng bày chỉ chia sẻ trong lớp và với cha mẹ.","hs":"- HS chụp và đưa được ảnh sản phẩm vào trang trưng bày kèm thông tin tác giả.\n- HS viết được lời nhận xét cụ thể, thiện chí cho sản phẩm của bạn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 1, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":5,"tiet":5,"bai":"Chủ đề 2: Một số dạng không gian trong tranh dân gian Việt Nam (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được cách diễn tả không gian, sắp xếp hình mảng trong tranh dân gian (Đông Hồ, Hàng Trống).\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- trân trọng giá trị nghệ thuật truyền thống của dân tộc.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.3 CB2 (Quản lí dữ liệu, thông tin và nội dung số): HS nêu được cách diễn tả không gian riêng của tranh dân gian.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu sáp hoặc màu goát, giấy vẽ, giấy màu, in đồ hoạ đơn giản (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến một số dạng không gian trong tranh dân gian việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về cách diễn tả không gian, sắp xếp hình mảng trong tranh dân gian (Đông Hồ, Hàng Trống).\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bộ sưu tập số tranh Đông Hồ, Hàng Trống trên trang của bảo tàng; HS phóng to từng bức để thấy tranh dân gian sắp xếp nhân vật to nhỏ theo vai trò chứ không theo xa gần, và nhận ra dòng chữ ghi tên dòng tranh dưới mỗi bức.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS so sánh một bức Đông Hồ với một bức Hàng Trống và ghi vào phiếu hai điểm khác nhau về màu và về nét.\n⚠ (Miền 4: An toàn) Tranh dân gian là di sản và mỗi bản chụp đều thuộc về nơi lưu giữ; khi dùng ảnh tranh vào bài của mình, HS ghi rõ tên tranh, dòng tranh và nơi cung cấp ảnh.","hs":"- HS nêu được cách diễn tả không gian riêng của tranh dân gian.\n- HS ghi được nguồn khi sử dụng ảnh tranh dân gian."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 2, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":6,"tiet":6,"bai":"Chủ đề 2: Một số dạng không gian trong tranh dân gian Việt Nam (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện cách diễn tả không gian, sắp xếp hình mảng trong tranh dân gian (Đông Hồ, Hàng Trống) thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- trân trọng giá trị nghệ thuật truyền thống của dân tộc.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu sáp hoặc màu goát, giấy vẽ, giấy màu, in đồ hoạ đơn giản (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến một số dạng không gian trong tranh dân gian việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác cách diễn tả không gian, sắp xếp hình mảng trong tranh dân gian (Đông Hồ, Hàng Trống)).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 2, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":7,"tiet":7,"bai":"Chủ đề 2: Một số dạng không gian trong tranh dân gian Việt Nam (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện cách diễn tả không gian, sắp xếp hình mảng trong tranh dân gian (Đông Hồ, Hàng Trống) theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- trân trọng giá trị nghệ thuật truyền thống của dân tộc.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu sáp hoặc màu goát, giấy vẽ, giấy màu, in đồ hoạ đơn giản (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến một số dạng không gian trong tranh dân gian việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 4).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện cách diễn tả không gian, sắp xếp hình mảng trong tranh dân gian (Đông Hồ, Hàng Trống) (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu sáp hoặc màu goát, giấy vẽ, giấy màu, in đồ hoạ đơn giản hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 2, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":8,"tiet":8,"bai":"Chủ đề 2: Một số dạng không gian trong tranh dân gian Việt Nam (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- trân trọng giá trị nghệ thuật truyền thống của dân tộc.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết được phần giới thiệu nêu rõ phần học hỏi và phần sáng tạo riêng.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu sáp hoặc màu goát, giấy vẽ, giấy màu, in đồ hoạ đơn giản (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến một số dạng không gian trong tranh dân gian việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS chụp sản phẩm và tự viết phần giới thiệu ba dòng: tên sản phẩm, em học được điều gì từ tranh dân gian, phần nào là ý riêng của em; GV ghép thành trang trưng bày của lớp.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS trình bày sản phẩm trước nhóm, nghe bạn hỏi và trả lời được câu hỏi về cách mình sắp xếp hình mảng.\n⚠ (Miền 4: An toàn) Nếu bài của em mượn hình từ một bức tranh dân gian thì phải nói rõ mượn từ bức nào, không nhận cả bức tranh của người xưa là sáng tạo của mình; ảnh chỉ chia sẻ trong lớp.","hs":"- HS viết được phần giới thiệu nêu rõ phần học hỏi và phần sáng tạo riêng.\n- HS trả lời được câu hỏi của bạn về sản phẩm của mình."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 2, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":9,"tiet":9,"bai":"Chủ đề 3: Cảnh đẹp quê hương (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được hình, mảng, đậm nhạt và màu sắc để thể hiện cảnh đẹp quê hương.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, tự hào về cảnh đẹp nơi mình sinh sống.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nhận ra bố cục của cảnh nhờ xem địa danh từ nhiều góc nhìn.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, vật liệu tạo tranh (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến cảnh đẹp quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về hình, mảng, đậm nhạt và màu sắc để thể hiện cảnh đẹp quê hương.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS dùng bản đồ số và ảnh toàn cảnh để xem lại một địa danh ở quê mình từ trên cao và từ mặt đất, nhận ra bố cục của cảnh: đâu là mảng chính, đâu là nền; góc nhìn từ trên cao là góc mà đứng dưới đất không bao giờ thấy được.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS chọn một địa danh, thu thập hai đến ba ảnh và ghi lại nguồn từng ảnh vào phiếu tư liệu.\n⚠ (Miền 4: An toàn) Chỉ tra cứu trong ứng dụng bản đồ và trang tư liệu GV chỉ định; không nhập địa chỉ nhà mình, không đánh dấu vị trí cá nhân lên bản đồ; ảnh lấy về phải ghi nguồn.","hs":"- HS nhận ra bố cục của cảnh nhờ xem địa danh từ nhiều góc nhìn.\n- HS lập được phiếu tư liệu ảnh có ghi nguồn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 3, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":10,"tiet":10,"bai":"Chủ đề 3: Cảnh đẹp quê hương (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện hình, mảng, đậm nhạt và màu sắc để thể hiện cảnh đẹp quê hương thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, tự hào về cảnh đẹp nơi mình sinh sống.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS xác định được mảng đậm nhạt của cảnh nhờ chuyển ảnh sang đen trắng.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, vật liệu tạo tranh (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến cảnh đẹp quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác hình, mảng, đậm nhạt và màu sắc để thể hiện cảnh đẹp quê hương).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS mở ảnh phong cảnh đã chọn trong phần mềm xem ảnh và chuyển ảnh sang chế độ đen trắng để nhìn rõ các mảng đậm nhạt đang bị màu sắc che lấp, nhờ đó xác định được đâu là mảng đậm nhất, đâu là mảng sáng nhất trước khi phác bố cục.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS phác bố cục mảng đậm nhạt trên giấy dựa vào ảnh đen trắng rồi mới chuyển sang vẽ màu.\n⚠ (Miền 4: An toàn) HS thao tác trên máy dùng chung của lớp, mở đúng thư mục ảnh của mình, không mở và không xoá tệp của bạn; chỉnh xong không lưu đè lên tệp ảnh gốc.","hs":"- HS xác định được mảng đậm nhạt của cảnh nhờ chuyển ảnh sang đen trắng.\n- HS phác được bố cục đậm nhạt trước khi vẽ màu."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 3, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":11,"tiet":11,"bai":"Chủ đề 3: Cảnh đẹp quê hương (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện hình, mảng, đậm nhạt và màu sắc để thể hiện cảnh đẹp quê hương theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, tự hào về cảnh đẹp nơi mình sinh sống.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, vật liệu tạo tranh (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến cảnh đẹp quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 4).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện hình, mảng, đậm nhạt và màu sắc để thể hiện cảnh đẹp quê hương (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, vật liệu tạo tranh hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 3, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":12,"tiet":12,"bai":"Chủ đề 3: Cảnh đẹp quê hương (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, tự hào về cảnh đẹp nơi mình sinh sống.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS tham gia sắp xếp và hoàn thiện trang triển lãm của lớp.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, vật liệu tạo tranh (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến cảnh đẹp quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp lập một trang triển lãm Cảnh đẹp quê hương gồm tranh của HS, mỗi tranh kèm tên địa danh và một câu giới thiệu; HS tự sắp xếp thứ tự tranh theo vùng để người xem dễ theo dõi.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS nhận xét tranh của bạn tập trung vào bố cục và cách dùng đậm nhạt, nói theo hướng góp ý chứ không phê phán.\n⚠ (Miền 4: An toàn) Tranh của ai thì ghi tên người ấy; ảnh chụp địa danh dùng làm tư liệu phải ghi nguồn ở cuối trang; trang triển lãm chia sẻ trong trường, muốn đưa lên trang của trường phải xin phép GV và cha mẹ.","hs":"- HS tham gia sắp xếp và hoàn thiện trang triển lãm của lớp.\n- HS nhận xét được tranh của bạn về bố cục và đậm nhạt."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 3, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":13,"tiet":13,"bai":"Chủ đề 4: Vẻ đẹp trong cuộc sống (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp của con người, đồ vật, hoạt động quen thuộc trong cuộc sống.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- biết trân trọng vẻ đẹp bình dị quanh mình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS mô tả được dáng và biểu cảm của người lao động qua ảnh tư liệu.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu sẵn có (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về vẻ đẹp của con người, đồ vật, hoạt động quen thuộc trong cuộc sống.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu loạt ảnh chụp người lao động đang làm việc: bác nông dân, cô lao công, chú thợ xây, người bán hàng; ảnh bắt đúng khoảnh khắc động cho HS thấy dáng người và biểu cảm mà quan sát thoáng qua ngoài đời không kịp ghi nhớ.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS chọn một ảnh, mô tả dáng người và đoán người trong ảnh đang nghĩ gì, cảm thấy thế nào.\n⚠ (Miền 4: An toàn) Ảnh chụp người lao động do GV lấy từ nguồn tư liệu có ghi tác giả; HS không chụp trộm người đang làm việc ngoài đường để lấy tư liệu, muốn chụp phải xin phép người ấy trước.","hs":"- HS mô tả được dáng và biểu cảm của người lao động qua ảnh tư liệu.\n- HS nêu được vì sao phải xin phép trước khi chụp ảnh người khác."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 4, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":14,"tiet":14,"bai":"Chủ đề 4: Vẻ đẹp trong cuộc sống (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện vẻ đẹp của con người, đồ vật, hoạt động quen thuộc trong cuộc sống thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- biết trân trọng vẻ đẹp bình dị quanh mình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu sẵn có (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác vẻ đẹp của con người, đồ vật, hoạt động quen thuộc trong cuộc sống).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 4, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":15,"tiet":15,"bai":"Chủ đề 4: Vẻ đẹp trong cuộc sống (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện vẻ đẹp của con người, đồ vật, hoạt động quen thuộc trong cuộc sống theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- biết trân trọng vẻ đẹp bình dị quanh mình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu sẵn có (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 4).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện vẻ đẹp của con người, đồ vật, hoạt động quen thuộc trong cuộc sống (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu vẽ, giấy vẽ, đất nặn, vật liệu sẵn có hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 4, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":16,"tiet":16,"bai":"Chủ đề 4: Vẻ đẹp trong cuộc sống (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- biết trân trọng vẻ đẹp bình dị quanh mình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS đặt được tên và viết được câu nêu thông điệp cho tác phẩm của mình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu sẵn có (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS chụp sản phẩm, tự đặt tên cho tác phẩm của mình và viết một câu nói rõ mình muốn người xem cảm nhận điều gì; GV ghép thành trang trưng bày của lớp.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS xem trang trưng bày và đoán thông điệp trong tác phẩm của bạn, sau đó nghe bạn nói lại để biết mình đoán có đúng không.\n⚠ (Miền 4: An toàn) Tác phẩm vẽ về một người lao động cụ thể thì chỉ ghi nghề nghiệp, không ghi họ tên và nơi làm việc của người ấy; ảnh sản phẩm chia sẻ trong lớp.","hs":"- HS đặt được tên và viết được câu nêu thông điệp cho tác phẩm của mình.\n- HS đọc được thông điệp trong tác phẩm của bạn và trao đổi lại."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 4, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":17,"tiet":17,"bai":"Kiểm tra, đánh giá cuối học kì I","yccd":"1. Năng lực mĩ thuật\n- Vận dụng kiến thức, kĩ năng đã học trong học kì để hoàn thành một sản phẩm mĩ thuật theo yêu cầu.\n- Thể hiện được yếu tố, nguyên lí tạo hình (hình, mảng, màu sắc, đậm nhạt) phù hợp nội dung.\n- Giới thiệu và nêu được cảm nhận về sản phẩm của mình.\n2. Năng lực chung\n- Tự chủ và tự học; giải quyết vấn đề và sáng tạo khi hoàn thành sản phẩm.\n3. Phẩm chất\n- Chăm chỉ, trung thực, có trách nhiệm; tự tin thể hiện sản phẩm của mình.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS tự sắp xếp và đánh giá được các sản phẩm của mình trong học kì.","dodung":"- Giáo viên: đề kiểm tra hoặc yêu cầu thực hành, tiêu chí đánh giá; thiết bị trình chiếu học liệu số.\n- Học sinh: đồ dùng học tập môn Mĩ thuật, giấy vẽ, màu vẽ, chất liệu đã chuẩn bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, nêu mục đích tiết kiểm tra cuối học kì I.\n- GV công bố yêu cầu và tiêu chí đánh giá sản phẩm.","hs":"- HS lắng nghe, nắm yêu cầu và tiêu chí."},{"ten":"2. Thực hành kiểm tra","gv":"- GV tổ chức cho HS làm bài thực hành: tạo một sản phẩm mĩ thuật theo chủ đề đã học trong học kì.\n- GV bao quát lớp, hỗ trợ khi cần, bảo đảm HS làm bài độc lập.","hs":"- HS thực hành tạo sản phẩm theo yêu cầu.\n- HS vận dụng kiến thức, kĩ năng đã học."},{"ten":"3. Trưng bày, đánh giá","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm.\n- GV nhận xét, đánh giá theo tiêu chí; ghi nhận sự tiến bộ của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS tự đánh giá và nhận xét sản phẩm của bạn."},{"ten":"4. Vận dụng - Dặn dò","gv":"- GV tổng kết tiết kiểm tra, tuyên dương HS.\n- GV dặn dò nội dung học tập tiếp theo.","hs":"- HS lắng nghe, ghi nhớ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS mở lại thư mục ảnh sản phẩm của mình trong học kì, tự xếp theo thứ tự từ bài chưa ưng ý đến bài ưng ý nhất và chỉ ra mình đã tiến bộ ở kĩ năng nào.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS chọn ba sản phẩm tiêu biểu đưa vào hồ sơ học tập và viết cho mỗi sản phẩm một dòng lí do chọn.\n⚠ (Miền 4: An toàn) HS chỉ mở thư mục mang tên mình, đặt tên tệp rõ ràng để dễ tìm; không mở, không sửa, không xoá tệp của bạn; hồ sơ học tập chỉ HS và GV cùng xem.","hs":"- HS tự sắp xếp và đánh giá được các sản phẩm của mình trong học kì.\n- HS lập được hồ sơ ba sản phẩm tiêu biểu kèm lí do chọn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Kiểm tra, đánh giá cuối học kì I"},
{"lop":4,"mon":"Mĩ thuật","tuan":18,"tiet":18,"bai":"Chủ đề 5: Những kỉ niệm đẹp (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được hình ảnh, hoạt động lưu giữ kỉ niệm; bố cục nhân vật và bối cảnh.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý thầy cô, bạn bè và những kỉ niệm tuổi học trò.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.3 CB2 (Quản lí dữ liệu, thông tin và nội dung số): HS phân tích được nhân vật chính và bối cảnh trong một bức ảnh kỉ niệm.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, ảnh tư liệu, giấy màu, vật liệu làm sản phẩm kỉ niệm (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến những kỉ niệm đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về hình ảnh, hoạt động lưu giữ kỉ niệm; bố cục nhân vật và bối cảnh.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu bộ ảnh kỉ niệm của lớp chụp trong năm học cùng vài ảnh tư liệu về các cách người ta lưu giữ kỉ niệm: album ảnh, sổ tay, tranh vẽ; HS nhận ra một khoảnh khắc có thể được lưu giữ bằng nhiều cách khác nhau.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS chọn một bức ảnh kỉ niệm và chỉ ra nhân vật chính, bối cảnh và điều gì làm bức ảnh ấy đáng nhớ.\n⚠ (Miền 4: An toàn) Ảnh kỉ niệm của lớp chỉ dùng trong lớp; trước khi đưa ảnh có mặt bạn vào bài, HS phải hỏi bạn; bạn nào không muốn hình mình xuất hiện thì phải tôn trọng.","hs":"- HS phân tích được nhân vật chính và bối cảnh trong một bức ảnh kỉ niệm.\n- HS nêu được nguyên tắc hỏi ý kiến bạn trước khi dùng ảnh có mặt bạn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 5, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":19,"tiet":19,"bai":"Chủ đề 5: Những kỉ niệm đẹp (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện hình ảnh, hoạt động lưu giữ kỉ niệm; bố cục nhân vật và bối cảnh thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý thầy cô, bạn bè và những kỉ niệm tuổi học trò.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS so sánh được các cách cắt khung và chọn bố cục làm nổi nhân vật chính.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, ảnh tư liệu, giấy màu, vật liệu làm sản phẩm kỉ niệm (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến những kỉ niệm đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác hình ảnh, hoạt động lưu giữ kỉ niệm; bố cục nhân vật và bối cảnh).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS dùng chức năng cắt ảnh trong phần mềm xem ảnh, thử cắt cùng một bức ảnh kỉ niệm theo ba khung khác nhau rồi so sánh khung nào làm nhân vật chính nổi bật, khung nào làm bức ảnh rối; cắt và hoàn tác được nhiều lần nên HS thử thoải mái.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS chọn khung ưng ý nhất làm bố cục cho bài vẽ của mình và giải thích lựa chọn đó.\n⚠ (Miền 4: An toàn) Thao tác trên bản sao của ảnh và giữ nguyên tệp gốc để không làm mất ảnh kỉ niệm chung của lớp; lưu bài vào thư mục của mình.","hs":"- HS so sánh được các cách cắt khung và chọn bố cục làm nổi nhân vật chính.\n- HS giải thích được lí do chọn bố cục cho bài của mình."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 5, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":20,"tiet":20,"bai":"Chủ đề 5: Những kỉ niệm đẹp (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện hình ảnh, hoạt động lưu giữ kỉ niệm; bố cục nhân vật và bối cảnh theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý thầy cô, bạn bè và những kỉ niệm tuổi học trò.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, ảnh tư liệu, giấy màu, vật liệu làm sản phẩm kỉ niệm (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến những kỉ niệm đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 4).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện hình ảnh, hoạt động lưu giữ kỉ niệm; bố cục nhân vật và bối cảnh (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu vẽ, ảnh tư liệu, giấy màu, vật liệu làm sản phẩm kỉ niệm hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 5, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":21,"tiet":21,"bai":"Chủ đề 5: Những kỉ niệm đẹp (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý thầy cô, bạn bè và những kỉ niệm tuổi học trò.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết được chú thích cho tác phẩm của mình trong album lớp.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, ảnh tư liệu, giấy màu, vật liệu làm sản phẩm kỉ niệm (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến những kỉ niệm đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp làm một trang album kỉ niệm gồm ảnh sản phẩm của tất cả HS, sắp xếp theo mốc thời gian trong năm học; mỗi HS viết một dòng chú thích cho tác phẩm của mình.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS đọc chú thích của bạn và viết lại một kỉ niệm chung mà chú thích ấy gợi cho mình nhớ.\n⚠ (Miền 4: An toàn) Album chỉ lưu trên máy của lớp và chiếu trong buổi sinh hoạt, không đăng lên mạng xã hội khi cha mẹ các bạn chưa đồng ý; không viết chú thích trêu chọc bạn.","hs":"- HS viết được chú thích cho tác phẩm của mình trong album lớp.\n- HS phản hồi tích cực với phần chú thích của bạn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 5, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":22,"tiet":22,"bai":"Chủ đề 6: Mái trường yêu dấu (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp của thiên nhiên, cây cối, con vật trong môi trường sống.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu thiên nhiên, có ý thức bảo vệ môi trường.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS chụp và chọn được góc trường có bố cục phù hợp để vẽ.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, lá cây, vật liệu tự nhiên (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường yêu dấu.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về vẻ đẹp của thiên nhiên, cây cối, con vật trong môi trường sống.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS dùng thiết bị của lớp chụp lại các góc của trường: cổng, hành lang, sân sau, gốc cây; sau đó xem lại trên màn hình lớn và chọn góc có bố cục đẹp nhất để vẽ, vì nhìn qua khung ảnh giúp nhận ra bố cục rõ hơn nhìn bằng mắt thường.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS giải thích vì sao góc mình chọn là đẹp: có mảng chính, có đường dẫn mắt, có khoảng trống hợp lí.\n⚠ (Miền 4: An toàn) Đi chụp theo nhóm và theo lộ trình GV giao, không leo trèo, không ra khỏi khu vực cho phép; chỉ chụp cảnh, nếu trong khung có bạn thì phải hỏi bạn trước.","hs":"- HS chụp và chọn được góc trường có bố cục phù hợp để vẽ.\n- HS giải thích được lí do chọn góc nhìn của mình."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 6, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":23,"tiet":23,"bai":"Chủ đề 6: Mái trường yêu dấu (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện vẻ đẹp của thiên nhiên, cây cối, con vật trong môi trường sống thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu thiên nhiên, có ý thức bảo vệ môi trường.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, lá cây, vật liệu tự nhiên (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường yêu dấu.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác vẻ đẹp của thiên nhiên, cây cối, con vật trong môi trường sống).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 6, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":24,"tiet":24,"bai":"Chủ đề 6: Mái trường yêu dấu (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện vẻ đẹp của thiên nhiên, cây cối, con vật trong môi trường sống theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu thiên nhiên, có ý thức bảo vệ môi trường.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, lá cây, vật liệu tự nhiên (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường yêu dấu.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 4).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện vẻ đẹp của thiên nhiên, cây cối, con vật trong môi trường sống (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu vẽ, giấy vẽ, giấy màu, lá cây, vật liệu tự nhiên hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 6, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":25,"tiet":25,"bai":"Chủ đề 6: Mái trường yêu dấu (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu thiên nhiên, có ý thức bảo vệ môi trường.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS đối chiếu được tranh vẽ của mình với ảnh chụp thực tế.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, lá cây, vật liệu tự nhiên (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường yêu dấu.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp ghép ảnh chụp các góc trường cùng tranh vẽ tương ứng thành trang trưng bày hai cột Ảnh chụp và Tranh vẽ; người xem so sánh được HS đã chọn giữ lại gì và lược bỏ gì so với thực tế.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS nhận xét theo đôi bạn: bạn đã lược bỏ chi tiết nào hợp lí, chi tiết nào tiếc vì bị bỏ mất.\n⚠ (Miền 4: An toàn) Ảnh chụp trường và tranh vẽ đều ghi tên tác giả; trang trưng bày dùng trong trường, muốn đưa lên trang thông tin của trường phải được GV và nhà trường đồng ý.","hs":"- HS đối chiếu được tranh vẽ của mình với ảnh chụp thực tế.\n- HS nhận xét được cách chọn lọc chi tiết của bạn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 6, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":26,"tiet":26,"bai":"Chủ đề 7: Môi trường xanh - sạch - đẹp (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được thông điệp bảo vệ môi trường qua sản phẩm mĩ thuật (tranh cổ động, mô hình).\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- có trách nhiệm giữ gìn môi trường xanh - sạch - đẹp.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.2 CB2 (Đánh giá dữ liệu, thông tin và nội dung số): HS đọc và ghi được số liệu về môi trường kèm nguồn tin cậy.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy các loại, vật liệu tái chế (chai, lọ, bìa cứng) (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường xanh - sạch - đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về thông điệp bảo vệ môi trường qua sản phẩm mĩ thuật (tranh cổ động, mô hình).\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem bộ ảnh chụp cùng một địa điểm trước và sau khi bị rác thải xâm chiếm, kèm số liệu về rác thải nhựa lấy từ trang của cơ quan nhà nước; ảnh đối chiếu và số liệu cho thấy vấn đề rõ hơn nhiều so với chỉ nghe kể.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS ghi lại một số liệu mình thấy ấn tượng nhất cùng tên trang đã cung cấp số liệu đó để đưa vào tranh cổ động.\n⚠ (Miền 4: An toàn) Số liệu về môi trường phải lấy từ trang của cơ quan nhà nước hoặc tổ chức có uy tín và ghi rõ nguồn; không chia sẻ lại ảnh gây sốc chưa rõ nơi chụp vì nhiều ảnh là của nơi khác hoặc đã bị chỉnh sửa.","hs":"- HS đọc và ghi được số liệu về môi trường kèm nguồn tin cậy.\n- HS nêu được vì sao phải kiểm tra nguồn trước khi tin và chia sẻ."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 7, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":27,"tiet":27,"bai":"Chủ đề 7: Môi trường xanh - sạch - đẹp (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện thông điệp bảo vệ môi trường qua sản phẩm mĩ thuật (tranh cổ động, mô hình) thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- có trách nhiệm giữ gìn môi trường xanh - sạch - đẹp.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS rút ra và vận dụng được nguyên tắc trình bày áp phích dễ đọc.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy các loại, vật liệu tái chế (chai, lọ, bìa cứng) (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường xanh - sạch - đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác thông điệp bảo vệ môi trường qua sản phẩm mĩ thuật (tranh cổ động, mô hình)).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) GV cho HS so sánh hai áp phích cùng nội dung, một bản chữ nhỏ nhiều chi tiết và một bản chữ to hình đơn giản màu tương phản; HS tự rút ra nguyên tắc thiết kế áp phích rồi phác thảo bố cục chữ và hình cho sản phẩm của mình.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV nhập câu khẩu hiệu của lớp vào một công cụ tạo hình bằng trí tuệ nhân tạo cho máy sinh vài phương án bố cục; HS đối chiếu với nguyên tắc vừa rút ra và chỉ ra phương án nào máy làm được, phương án nào máy viết sai chữ tiếng Việt hoặc đặt hình lệch ý nghĩa.\n⚠ (Miền 4: An toàn) Hình do máy sinh chỉ dùng để bàn về bố cục, không đưa nguyên vào sản phẩm rồi nhận là mình vẽ; khẩu hiệu phải do HS tự nghĩ; GV là người thao tác công cụ, HS không dùng tài khoản riêng.","hs":"- HS rút ra và vận dụng được nguyên tắc trình bày áp phích dễ đọc.\n- HS chỉ ra được điểm được và chưa được của phương án do máy sinh ra."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 7, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":28,"tiet":28,"bai":"Chủ đề 7: Môi trường xanh - sạch - đẹp (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện thông điệp bảo vệ môi trường qua sản phẩm mĩ thuật (tranh cổ động, mô hình) theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- có trách nhiệm giữ gìn môi trường xanh - sạch - đẹp.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy các loại, vật liệu tái chế (chai, lọ, bìa cứng) (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường xanh - sạch - đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 4).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện thông điệp bảo vệ môi trường qua sản phẩm mĩ thuật (tranh cổ động, mô hình) (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu vẽ, giấy các loại, vật liệu tái chế (chai, lọ, bìa cứng) hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 7, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":29,"tiet":29,"bai":"Chủ đề 7: Môi trường xanh - sạch - đẹp (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- có trách nhiệm giữ gìn môi trường xanh - sạch - đẹp.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 2.2 CB2 (Chia sẻ thông tin qua công nghệ số): HS đóng góp tranh và khẩu hiệu cho trang tuyên truyền của lớp.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy các loại, vật liệu tái chế (chai, lọ, bìa cứng) (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường xanh - sạch - đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) Lớp lập trang tuyên truyền Môi trường xanh sạch đẹp gồm tranh cổ động của HS kèm khẩu hiệu, gửi tới các lớp trong trường qua màn hình sinh hoạt dưới cờ.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS ghi ở cuối trang nguồn của mọi số liệu và hình ảnh tham khảo đã sử dụng, ghi tên tác giả cho từng bức tranh.\n⚠ (Miền 4: An toàn) Thông điệp tuyên truyền phải đúng sự thật, không phóng đại số liệu để gây chú ý; chỉ chia sẻ trong phạm vi nhà trường, muốn đăng rộng hơn phải được nhà trường cho phép.","hs":"- HS đóng góp tranh và khẩu hiệu cho trang tuyên truyền của lớp.\n- HS ghi đủ nguồn tư liệu và tên tác giả trên sản phẩm chung."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 7, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":30,"tiet":30,"bai":"Chủ đề 8: Quê hương thanh bình (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được hình ảnh cuộc sống yên bình nơi quê hương qua bố cục tranh, sản phẩm 3D.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, đất nước, trân trọng cuộc sống hoà bình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS so sánh được cách thể hiện sự thanh bình ở các vùng miền.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu tạo mô hình (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến quê hương thanh bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về hình ảnh cuộc sống yên bình nơi quê hương qua bố cục tranh, sản phẩm 3D.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem bộ tranh và ảnh về cuộc sống làng quê ở các vùng miền, chú ý cách các tác giả chọn khoảnh khắc yên bình: buổi chiều thả diều, phiên chợ sớm, con đò qua sông; mỗi tác phẩm đều có ghi tên tác giả.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS chọn hai tác phẩm khác vùng miền và ghi vào phiếu điểm giống nhau về cảm xúc, điểm khác nhau về cảnh vật.\n⚠ (Miền 4: An toàn) Khi đưa ảnh tham khảo vào phiếu tư liệu, HS ghi tên tác giả và nơi lấy ảnh; không cắt bỏ chữ kí, tên tác giả trên tranh của người khác.","hs":"- HS so sánh được cách thể hiện sự thanh bình ở các vùng miền.\n- HS ghi đúng tên tác giả cho tranh, ảnh mình tham khảo."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 8, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":31,"tiet":31,"bai":"Chủ đề 8: Quê hương thanh bình (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện hình ảnh cuộc sống yên bình nơi quê hương qua bố cục tranh, sản phẩm 3D thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, đất nước, trân trọng cuộc sống hoà bình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS lấy được bảng màu chủ đạo từ một bức ảnh và đối chiếu với màu vẽ thật.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu tạo mô hình (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến quê hương thanh bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác hình ảnh cuộc sống yên bình nơi quê hương qua bố cục tranh, sản phẩm 3D).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS dùng công cụ chọn màu trong phần mềm xem ảnh để lấy ra bảng năm màu chủ đạo của một bức ảnh làng quê mình thích, rồi đối chiếu với hộp màu của mình xem pha được những màu nào.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS lập bảng màu cho bài của mình dựa trên kết quả vừa lấy và thử màu ra giấy nháp trước khi vẽ.\n⚠ (Miền 4: An toàn) HS thao tác trên máy của lớp, thoát phần mềm và trả máy đúng chỗ sau khi dùng; màu trên màn hình sáng hơn màu bột trên giấy nên phải thử ra giấy nháp, không tin hoàn toàn vào màu hiển thị.","hs":"- HS lấy được bảng màu chủ đạo từ một bức ảnh và đối chiếu với màu vẽ thật.\n- HS lập được bảng màu cho bài vẽ của mình."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 8, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":32,"tiet":32,"bai":"Chủ đề 8: Quê hương thanh bình (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện hình ảnh cuộc sống yên bình nơi quê hương qua bố cục tranh, sản phẩm 3D theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, đất nước, trân trọng cuộc sống hoà bình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu tạo mô hình (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến quê hương thanh bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 4).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện hình ảnh cuộc sống yên bình nơi quê hương qua bố cục tranh, sản phẩm 3D (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu vẽ, giấy vẽ, đất nặn, vật liệu tạo mô hình hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 8, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":33,"tiet":33,"bai":"Chủ đề 8: Quê hương thanh bình (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, đất nước, trân trọng cuộc sống hoà bình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết được phần giới thiệu ngắn cho tranh của mình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu tạo mô hình (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến quê hương thanh bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp làm trang trưng bày Quê hương thanh bình xếp tranh theo vùng miền; mỗi HS viết ba dòng giới thiệu gồm tên tranh, nơi được vẽ và cảm xúc mình muốn gửi gắm.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS đọc phần giới thiệu của bạn rồi viết một câu phản hồi chân thành, tránh nhận xét chung chung kiểu đẹp lắm.\n⚠ (Miền 4: An toàn) Trang trưng bày ghi tên tác giả từng tranh và nguồn ảnh tham khảo; chia sẻ trong lớp và với cha mẹ, không đăng công khai khi chưa được đồng ý.","hs":"- HS viết được phần giới thiệu ngắn cho tranh của mình.\n- HS viết được phản hồi cụ thể cho tác phẩm của bạn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 8, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":34,"tiet":34,"bai":"Kiểm tra, đánh giá cuối học kì II","yccd":"1. Năng lực mĩ thuật\n- Vận dụng kiến thức, kĩ năng đã học trong học kì để hoàn thành một sản phẩm mĩ thuật theo yêu cầu.\n- Thể hiện được yếu tố, nguyên lí tạo hình (hình, mảng, màu sắc, đậm nhạt) phù hợp nội dung.\n- Giới thiệu và nêu được cảm nhận về sản phẩm của mình.\n2. Năng lực chung\n- Tự chủ và tự học; giải quyết vấn đề và sáng tạo khi hoàn thành sản phẩm.\n3. Phẩm chất\n- Chăm chỉ, trung thực, có trách nhiệm; tự tin thể hiện sản phẩm của mình.","dodung":"- Giáo viên: đề kiểm tra hoặc yêu cầu thực hành, tiêu chí đánh giá; thiết bị trình chiếu học liệu số.\n- Học sinh: đồ dùng học tập môn Mĩ thuật, giấy vẽ, màu vẽ, chất liệu đã chuẩn bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, nêu mục đích tiết kiểm tra cuối học kì II.\n- GV công bố yêu cầu và tiêu chí đánh giá sản phẩm.","hs":"- HS lắng nghe, nắm yêu cầu và tiêu chí."},{"ten":"2. Thực hành kiểm tra","gv":"- GV tổ chức cho HS làm bài thực hành: tạo một sản phẩm mĩ thuật theo chủ đề đã học trong học kì.\n- GV bao quát lớp, hỗ trợ khi cần, bảo đảm HS làm bài độc lập.","hs":"- HS thực hành tạo sản phẩm theo yêu cầu.\n- HS vận dụng kiến thức, kĩ năng đã học."},{"ten":"3. Trưng bày, đánh giá","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm.\n- GV nhận xét, đánh giá theo tiêu chí; ghi nhận sự tiến bộ của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS tự đánh giá và nhận xét sản phẩm của bạn."},{"ten":"4. Vận dụng - Dặn dò","gv":"- GV tổng kết tiết kiểm tra, tuyên dương HS.\n- GV dặn dò nội dung học tập tiếp theo.","hs":"- HS lắng nghe, ghi nhớ."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Kiểm tra, đánh giá cuối học kì II"},
{"lop":4,"mon":"Mĩ thuật","tuan":35,"tiet":35,"bai":"Trưng bày sản phẩm và tổng kết năm học","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu được các sản phẩm mĩ thuật tiêu biểu đã làm trong năm học.\n- Nêu được cảm nhận, nhận xét về sản phẩm của mình và của bạn.\n- Nhận ra sự tiến bộ của bản thân qua các sản phẩm mĩ thuật.\n2. Năng lực chung\n- Giao tiếp và hợp tác: cùng nhau tổ chức, sắp xếp không gian trưng bày.\n- Tự chủ và tự học: tự lựa chọn, giới thiệu sản phẩm của mình.\n3. Phẩm chất\n- Yêu thích môn học; tự tin, trân trọng thành quả của mình và của bạn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS tham gia dựng trang triển lãm số và viết đúng chú thích cho sản phẩm.","dodung":"- Giáo viên: không gian trưng bày, bảng hoặc giá treo sản phẩm; thiết bị trình chiếu học liệu số.\n- Học sinh: các sản phẩm mĩ thuật đã làm trong năm học; đồ dùng để trưng bày.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tạo không khí vui tươi cho tiết tổng kết cuối năm.\n- GV giới thiệu ý nghĩa của buổi trưng bày sản phẩm mĩ thuật.","hs":"- HS hào hứng tham gia.\n- HS lắng nghe."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS lựa chọn, sắp xếp các sản phẩm tiêu biểu của mình theo chủ đề hoặc nhóm.\n- GV gợi ý cách bố trí không gian trưng bày đẹp, khoa học.","hs":"- HS lựa chọn sản phẩm, sắp xếp theo hướng dẫn.\n- HS cùng nhau trang trí khu trưng bày."},{"ten":"3. Luyện tập - Trưng bày, giới thiệu","gv":"- GV tổ chức cho HS trưng bày và giới thiệu sản phẩm trước lớp.\n- GV khuyến khích HS nêu cảm nhận, nhận xét về sản phẩm của bạn.","hs":"- HS giới thiệu sản phẩm của mình.\n- HS quan sát, nhận xét sản phẩm của bạn."},{"ten":"4. Vận dụng - Tổng kết năm học","gv":"- GV cùng HS nhìn lại chặng đường học tập môn Mĩ thuật trong năm.\n- GV tuyên dương, động viên; gợi mở việc tiếp tục sáng tạo trong dịp hè.","hs":"- HS chia sẻ điều tâm đắc nhất trong năm học.\n- HS nêu mong muốn tiếp tục học và sáng tạo mĩ thuật."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS cùng GV dựng một trang triển lãm số cuối năm chia theo tám chủ đề đã học, mỗi chủ đề chọn vài sản phẩm tiêu biểu; HS phụ trách phần chú thích gồm tên chủ đề, tên tác giả và chất liệu.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS đóng vai người thuyết minh, giới thiệu một chủ đề trong triển lãm cho khách tham quan là các bạn lớp khác và cha mẹ.\n⚠ (Miền 4: An toàn) Triển lãm ghi đủ tên tác giả cho từng sản phẩm và ghi nguồn cho mọi hình ảnh tham khảo; chỉ chiếu trong buổi tổng kết ở trường, đưa lên mạng phải được nhà trường và cha mẹ đồng ý.","hs":"- HS tham gia dựng trang triển lãm số và viết đúng chú thích cho sản phẩm.\n- HS thuyết minh được một chủ đề của triển lãm trước người xem."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Trưng bày, tổng kết cuối năm"}
];
